#!/usr/bin/env bash
# Show this project in the Fyso menu bar app (D85, replaces the SwiftBar plugin of D34): add it
# to the app's instance list, the installer's registry (port<TAB>folder). Projects created from
# the app are already listed; this is for projects generated by hand.
set -euo pipefail
source "$(dirname "$0")/lib.sh"
[ "$(uname -s)" = Darwin ] || fail 'the Fyso menu bar app is macOS only.'
# The app's own CLI does it when installed (~/.local/bin/fyso links to the app).
if command -v fyso >/dev/null 2>&1 && fyso add "$PWD"; then exit 0; fi
home="${FYSO_HOME:-$HOME/Library/Application Support/Fyso}"
registry="$home/projects.tsv"
mkdir -p "$home"
if [ -f "$registry" ] && cut -f2 "$registry" | grep -Fxq "$PWD"; then
  echo "Already listed in the Fyso menu bar app."
  exit 0
fi
printf '%s\t%s\n' "$FYSO_HTTP_PORT" "$PWD" >> "$registry"
echo "Listed in the Fyso menu bar app. Install the app from Fyso.dmg if it is not on this Mac yet."
